{
  "answers": [
    {
      "question_id": "Q1",
      "question": "At what point do you consider yourself 'running late' — is there a specific time, such as a number of minutes before the childcare centre's drop-off deadline, that triggers the decision to notify someone?",
      "answer": "The trigger is whether the assigned escort can meet the arrival window set by the childcare provider. If that window cannot be met, a delay notice is sent. The exact number of minutes before the deadline that triggers this is not specified in the workflow."
    },
    {
      "question_id": "Q2",
      "question": "When you need to let someone know you are running late, who do you contact — is it a childcare staff member, a co-parent or partner, another caregiver, or a combination of people?",
      "answer": "When running late, the mother sends an arrival delay notice to the childcare teacher. If the escort cannot make the window, the backup caregiver is also confirmed and the teacher is notified. The partner may be involved in escort coordination but is not a primary recipient of the delay notice."
    },
    {
      "question_id": "Q3",
      "question": "How do you confirm that the drop-off is complete — for example, do you sign your child in at the centre, receive an acknowledgement from a staff member, or is there no formal handoff step?",
      "answer": "Drop-off is confirmed through an in-person handover with the childcare teacher, who provides a handover confirmation. This is recorded in the attendance register. An unacknowledged handover is treated as an exception, so acknowledgement from the teacher is a required step."
    },
    {
      "question_id": "Q4",
      "question": "What does packing involve each morning — do you work from a fixed list of items, or does it vary day to day, and do you use any tool such as a written list or app to track what needs to go?",
      "answer": "Packing is guided by a daily item list reviewed each morning, suggesting it can vary day to day. The partner reviews this list and then packs and checks the bag. A packing checklist is used as a supporting tool. Missing items trigger a resolution step before departure."
    },
    {
      "question_id": "Q5",
      "question": "What happens if an unexpected disruption occurs — such as your child being unwell, the childcare centre being closed, or a key item being unavailable — and is there a set process you follow in those situations?",
      "answer": "Recognised exceptions include a missing required item, escort unavailability, arrival delay, and unacknowledged handover. For missing items, an agreed substitute is checked or the teacher is contacted. For escort issues, a backup caregiver is confirmed. Scenarios like the child being unwell or the centre being closed are not specified."
    },
    {
      "question_id": "Q6",
      "question": "How many days per week does this drop-off routine take place, and does the schedule stay the same each week or does it change depending on the day or other commitments?",
      "answer": "The routine takes place on weekday mornings. The exact number of days per week and whether the schedule varies day to day or week to week is not specified in the workflow."
    }
  ]
}
